-- ============================================================================
-- DR1 PROFESSIONAL DEEP SEED: Well Design & Surveys, intermediate tier.
--
-- Six modules, 26 lessons, 132 questions (15 per module bank plus a 42
-- question final exam). The structure row is GENERATED from the tier's
-- manifest.json rather than hand typed, so the seeded structure and the
-- shipped lesson files cannot disagree.
--
-- What this tier owns: how far the reported position could be from the true
-- one. Three instruments and what each is bad at; why survey errors do not
-- average out, because a bias is the same at every station and a declination
-- error is one rotation of the whole well; the three propagation modes and
-- the factor of ten that the order of squaring produces over a hundred
-- stations; the weighting functions and the position-sensitivity matrix that
-- carry a sensor error into a covariance; the ISCWSA MWD Rev4 validation
-- well, reproduced to machine precision, and why that is verification and not
-- validation; the borehole frame, in which along hole, highside and lateral
-- answer three different questions; the two-dimensional confidence factors,
-- which are not the one-dimensional ones; the budget, in which five of
-- twenty-seven sources pay for most of the answer and the ranking changes
-- completely with attitude; and the five things that must accompany a quoted
-- ellipse before it can be compared with anything.
--
-- Every number in the lessons is derived by running the vendored
-- engines/drilling against its own goldens, and the teaching lab that the
-- panels and this course share is pinned to the same values by
-- welldesignLab.test.js. A numeric sweep over the lessons resolved all
-- literals carrying seven or more significant figures to an engine-derived
-- value; a tier-leakage sweep over the lessons and the banks reports zero
-- downward leaks and zero same-tier answer prints against all eighteen
-- graded fields.
--
-- Answer keys live only here and in academy_quiz_questions, which has no
-- client SELECT policy.
-- ============================================================================

values ('welldesign', 'intermediate', '{"modules":[{"key":"m01-why-a-position-is-uncertain","title":"Why a Position Is Uncertain","lesson_keys":["l01-a-survey-is-a-measurement","l02-the-three-sensor-sets","l03-error-sources-and-their-codes","l04-the-three-propagation-modes","l05-the-reference-the-model-needs"]},{"key":"m02-the-iscwsa-model","title":"The ISCWSA Model","lesson_keys":["l01-what-a-weighting-function-is","l02-from-sensor-error-to-position-error","l03-building-the-covariance","l04-the-validation-case","l05-machine-precision-against-a-workbook"]},{"key":"m03-reading-the-covariance","title":"Reading the Covariance","lesson_keys":["l01-nev-and-what-it-hides","l02-the-borehole-frame","l03-highside-lateral-and-along-hole","l04-the-horizontal-ellipse","l05-confidence-and-the-k-you-multiply-by"]},{"key":"m04-the-budget","title":"The Budget","lesson_keys":["l01-which-sources-dominate","l02-the-ranking-changes-with-attitude","l03-depth-only-sources","l04-what-to-do-about-the-biggest-one"]},{"key":"m05-using-the-number","title":"Using the Number","lesson_keys":["l01-uncertainty-in-a-target","l02-uncertainty-in-a-tvd","l03-quoting-an-ellipse-honestly","l04-what-the-model-does-not-include"]},{"key":"m06-the-professional-reading","title":"The Professional Reading","lesson_keys":["l01-the-story-so-far","l02-working-the-capstone","l03-onward"]}]}'::jsonb, 1)
