insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('welldesign', 'intermediate', 'module', 'm01-why-a-position-is-uncertain', 1, 'Which instrument gives inclination?', '["A pendulum and an inclinometer.", "Three accelerometers, which measure the direction of gravity in the tool frame.", "Three magnetometers, resolved against the tool axis to give the angle between the hole and the vertical.", "The depth counter, combined with the true vertical depth increment measured over each survey interval."]'::jsonb, 1, 'Gravity is large, constant, and well known, which is why accelerometer inclination is typically good to about a tenth of a degree.'),
  ('welldesign', 'intermediate', 'module', 'm01-why-a-position-is-uncertain', 2, 'Why must a survey be taken with the string stationary?', '["Because any acceleration adds to gravity and corrupts the accelerometer reading.", "Because the magnetometers need time.", "Because the depth counter cannot resolve the measured depth while the pipe is moving through the rotary table.", "Because the tool telemetry cannot transmit while mud is being circulated through the bit at drilling rates."]'::jsonb, 0, 'That is why the survey interval is set by connections rather than chosen: you survey where the string is already stopped.'),
  ('welldesign', 'intermediate', 'module', 'm01-why-a-position-is-uncertain', 3, 'Why do accelerometers change formulation near horizontal?', '["Because the tool sags at high angle.", "Because the cross-axial sensors saturate at high inclination, so the axial reading must be used on its own instead.", "Because the toolface becomes undefined at horizontal, and the inclination formula depends on the toolface angle.", "Because the axial component of gravity goes to zero at ninety degrees."]'::jsonb, 3, 'Near horizontal the inclination is derived from the two cross-axial sensors instead, and the error geometry changes with it.'),
  ('welldesign', 'intermediate', 'module', 'm01-why-a-position-is-uncertain', 4, 'Why are magnetometers worse than accelerometers?', '["Because they have fewer sensing axes.", "Because they are mounted further from the bit, so the survey they report applies to a shallower point in the hole.", "Because the earth''s field is small, varies with place and time, and there is steel nearby.", "Because they must be temperature corrected and the accelerometers do not, which adds a calibration step."]'::jsonb, 2, 'Every one of those three is a reason a magnetic azimuth carries more uncertainty than an inclination does.'),
  ('welldesign', 'intermediate', 'module', 'm01-why-a-position-is-uncertain', 5, 'Where does magnetic azimuth fail worst?', '["Near vertical, where the horizontal projection the azimuth lives in nearly vanishes.", "At forty-five degrees inclination.", "Near horizontal, where the axial magnetometer reads most of the field and the cross-axial pair read little of it.", "Wherever the total field strength exceeds the model value, which drives the resolved azimuth toward the axial direction."]'::jsonb, 0, 'At exactly zero inclination azimuth is undefined. The error model carries a vertical inclination limit and switches formulation below it.'),
  ('welldesign', 'intermediate', 'module', 'm01-why-a-position-is-uncertain', 6, 'Why does the tool sit in a non-magnetic collar?', '["Because steel is too heavy at depth.", "Because steel collars channel the earth''s field along the hole and bias the azimuth.", "Because a magnetic collar would be pulled toward the low side of the hole, introducing a mechanical misalignment.", "Because the accelerometers cannot read gravity through a ferrous housing, which shields the sensor package."]'::jsonb, 1, 'How much non-magnetic spacing is needed above and below the tool is itself a design calculation.'),
  ('welldesign', 'intermediate', 'module', 'm01-why-a-position-is-uncertain', 7, 'Which hole orientation is worst for magnetic azimuth?', '["East-west at low dip.", "Vertical, since the horizontal component of the earth''s field is fully available and the geometry is well conditioned.", "Any hole at forty-five degrees, where the axial and cross-axial magnetometers contribute equally to the resolved azimuth.", "North-south at high magnetic dip."]'::jsonb, 3, 'That is the axial interference geometry the largest error source in this course''s validation well exploits.'),
  ('welldesign', 'intermediate', 'module', 'm01-why-a-position-is-uncertain', 8, 'What are the three propagation modes?', '["Bias, scale factor, and misalignment.", "Depth, inclination, and azimuth, corresponding to the three quantities a survey station actually measures.", "Random, systematic, and global.", "Independent, correlated, and anti-correlated, describing how each station''s error relates to its neighbours."]'::jsonb, 2, 'The mode says how a source''s value repeats across stations, and that determines how its effect accumulates down the well.'),
  ('welldesign', 'intermediate', 'module', 'm01-why-a-position-is-uncertain', 9, 'How does a random source''s position error grow with station count?', '["As the square root of the number of stations.", "Linearly with the number of stations.", "It does not grow at all, because independent errors cancel exactly in the limit of many survey stations.", "As the square of the number of stations, since each station contributes to every deeper one in the accumulation."]'::jsonb, 0, 'Contributions add in variance because each station''s value is independent, so a hundred stations give ten times one station''s error.'),
  ('welldesign', 'intermediate', 'module', 'm01-why-a-position-is-uncertain', 10, 'A bias fixed for the whole run acts at every station. What does that do to the total?', '["As the square root of the count.", "Linearly, because one value applies at every station in the run.", "It grows as the square of the count, since the same value applies at every station and every station affects every deeper one.", "It does not depend on the station count at all, only on the total measured depth over which the source acts."]'::jsonb, 1, 'Contributions add in amplitude before squaring. Against a random source of the same size at a hundred stations, that is a factor of ten.'),
  ('welldesign', 'intermediate', 'module', 'm01-why-a-position-is-uncertain', 11, 'What makes declination a global source?', '["It changes at every station.", "It is a property of the tool that is fixed for the duration of one survey run but differs between runs.", "It is measured at surface rather than downhole, so it applies to the whole well but not to other wells nearby.", "It takes one value for the location, so it is wrong the same way for every well there."]'::jsonb, 3, 'That distinction matters for anti-collision: two wells sharing a global source have correlated errors that do not add in the usual way.'),
  ('welldesign', 'intermediate', 'module', 'm01-why-a-position-is-uncertain', 12, 'Why does surveying more often not fix the uncertainty?', '["Because the largest sources are systematic and global, and neither improves with station count.", "Because the tool has a fixed error floor.", "Because a shorter survey interval increases the number of connections, and each connection adds depth counting error.", "Because the minimum curvature assumption is the dominant error, and it does not improve as the interval shortens."]'::jsonb, 0, 'A well surveyed with a hundred stations is not ten times better than one surveyed with ten, which is the crux of the whole model.'),
  ('welldesign', 'intermediate', 'module', 'm01-why-a-position-is-uncertain', 13, 'What two header values does the error model refuse to run without?', '["Declination and grid convergence.", "The surface latitude and longitude, from which the field model computes everything else the calculation needs.", "Total magnetic field strength and dip angle.", "The tool type and the survey interval, which together determine which weighting functions the model should apply."]'::jsonb, 2, 'Every magnetometer weighting function contains both. Without them a sensor error in nanotesla cannot be turned into an azimuth error at all.'),
  ('welldesign', 'intermediate', 'module', 'm01-why-a-position-is-uncertain', 14, 'Why does magnetic dip matter to azimuth accuracy?', '["Because dip sets the tool''s toolface.", "Because high dip leaves little horizontal field, and azimuth is that field''s direction.", "Because the dip angle is subtracted from the measured inclination to give the true angle relative to the earth''s field.", "Because dip determines the declination, which is the correction applied to convert magnetic azimuth into true azimuth."]'::jsonb, 1, 'At the magnetic equator dip is zero and the field is all horizontal. Near the poles the horizontal component nearly vanishes.'),
  ('welldesign', 'intermediate', 'module', 'm01-why-a-position-is-uncertain', 15, 'What does the error model produce at each station?', '["A single position error in metres.", "A corrected position, obtained by subtracting the estimated bias of each error source from the computed position.", "A confidence interval on measured depth, inclination, and azimuth separately, which the user then combines.", "A covariance matrix describing an ellipsoid of possible true positions."]'::jsonb, 3, 'Three variances and three covariances. Turning that into a single quotable number is a separate decision made later.'),
  ('welldesign', 'intermediate', 'module', 'm02-the-iscwsa-model', 1, 'What does a weighting function return?', '["The magnitude of the error source.", "The position error in north, east, and vertical that the source causes at the station it is evaluated at.", "The derivative of depth, inclination, and azimuth with respect to one error source.", "A scalar multiplier applied to the source''s magnitude, which converts nanotesla into degrees of azimuth error."]'::jsonb, 2, 'Three numbers per station, in what the standard calls DIA space. The step from DIA to position is a separate matrix.'),
  ('welldesign', 'intermediate', 'module', 'm02-the-iscwsa-model', 2, 'Where do the weighting functions come from?', '["From differentiating the survey equations with respect to each sensor error.", "From field calibration of each tool.", "From a Monte Carlo simulation over the sensor error distributions, tabulated against inclination and azimuth.", "From the manufacturer''s specification sheet, which states the sensitivity of each sensor to its own error terms."]'::jsonb, 0, 'The results are trigonometric expressions in inclination, azimuth, dip, and field strength, published in the standard.'),
  ('welldesign', 'intermediate', 'module', 'm02-the-iscwsa-model', 3, 'In the code ABXY-TI1S, what does the first letter mean?', '["Axial, naming the sensor direction.", "Accelerometer, naming which instrument the error belongs to.", "Azimuth, naming the survey quantity the error ultimately affects once the weighting function has been applied.", "Absolute, distinguishing a fixed offset from a proportional one such as a scale factor error term."]'::jsonb, 1, 'D for depth, A for accelerometer, M for magnetometer. The scheme is terse and once it is clear the list reads itself.'),
  ('welldesign', 'intermediate', 'module', 'm02-the-iscwsa-model', 4, 'In the code MBZ, what does the Z mean?', '["Zero offset, meaning a bias term.", "The vertical axis in the map frame, which is the direction the error propagates into at the surveyed station.", "The third of three formulations, applied where the first two are singular at the extremes of inclination.", "The axial sensor, the one along the tool."]'::jsonb, 3, 'XY is the cross-axial pair together, Z is the axial one. So MBZ is a magnetometer bias on the axial sensor.'),
  ('welldesign', 'intermediate', 'module', 'm02-the-iscwsa-model', 5, 'What does the matrix the standard calls dr/dp do?', '["It turns depth, inclination, and azimuth errors at each station into position errors.", "It rotates the covariance into HLA.", "It differentiates the position with respect to the source magnitude, combining both steps into one operation.", "It converts the magnetic azimuth into the true azimuth, using the declination and convergence in the header."]'::jsonb, 0, 'It is the second derivative in the chain. The first takes a sensor error to a survey error; this one takes it to a position.'),
  ('welldesign', 'intermediate', 'module', 'm02-the-iscwsa-model', 6, 'Why is dr/dp not diagonal?', '["Because the survey interval varies.", "Because inclination and azimuth errors are correlated, so the off-diagonal terms carry that correlation.", "Because a change in attitude at one station moves every station below it.", "Because the matrix includes the ratio factor, which couples adjacent intervals through their shared dogleg."]'::jsonb, 2, 'That is the whole reason survey errors accumulate. The position at total depth depends on the attitude at every station above it.'),
  ('welldesign', 'intermediate', 'module', 'm02-the-iscwsa-model', 7, 'What two accumulators does the engine build per source?', '["The mean and the variance.", "The per-station sensitivity, and the running sum of sensitivities down to each station.", "The covariance in the map frame and the covariance in the borehole frame, computed side by side at each station.", "The bias contribution and the scale factor contribution, which are propagated under different rules."]'::jsonb, 1, 'Random propagation needs the first because contributions add in variance. Systematic and global need the second.'),
  ('welldesign', 'intermediate', 'module', 'm02-the-iscwsa-model', 8, 'What does the error model return per source?', '["Only its contribution to the total.", "Its magnitude and its weighting function evaluated at each station, from which the user computes the covariance.", "A single scalar variance at each station, which the model then sums across sources to give the total.", "Its code, its propagation mode, a depth-only flag, its sensitivities, and its own covariance."]'::jsonb, 3, 'Keeping the per-source covariances rather than only the sum is what makes a budget possible at all.'),
  ('welldesign', 'intermediate', 'module', 'm02-the-iscwsa-model', 9, 'Why does the prepared survey hold true azimuths?', '["Because the position accumulation needs the angle in the frame the positions live in.", "Because true north is easier to compute.", "Because the magnetic weighting functions are defined relative to true north, which is why the conversion happens first.", "Because the declination is unknown at the time the survey is taken, so true azimuth is the only available reference."]'::jsonb, 0, 'The magnetic weighting functions need the angle relative to MAGNETIC north, so the model carries both and converts where each is needed.'),
  ('welldesign', 'intermediate', 'module', 'm02-the-iscwsa-model', 10, 'What happens if the header''s azimuth reference is misread?', '["The model refuses to run.", "The whole answer is rotated, and nothing in the output reveals it.", "Only the magnetometer sources are affected, since the accelerometer weighting functions have no azimuth dependence.", "The totals stay correct while the per-source breakdown is scrambled, because the sum is invariant to the rotation."]'::jsonb, 1, 'A rotation of the whole covariance looks entirely plausible. That is why the header has to be read rather than assumed.'),
  ('welldesign', 'intermediate', 'module', 'm02-the-iscwsa-model', 11, 'What is the validation case?', '["A field trial against gyro surveys.", "A synthetic well generated at random, used to confirm that the model produces finite output over the full range.", "A published well with expected results, so any implementation can be checked against it.", "The operator''s own offset well data, against which the service company calibrates its tool error parameters."]'::jsonb, 2, 'It is 268 stations and 8000 m, starting vertical and ending horizontal on a 75 degree azimuth.'),
  ('welldesign', 'intermediate', 'module', 'm02-the-iscwsa-model', 12, 'Why does a published model need a validation case at all?', '["Because the standard requires one.", "Because the weighting functions cannot be derived analytically, so the reference values are the only definition available.", "Because the model''s parameters vary by tool, and the case fixes one parameter set that everybody can use.", "Because a model described in a paper is not a model until two implementations agree."]'::jsonb, 3, 'The weighting functions carry sign conventions, singular cases, and frame choices. A plausible implementation can be wrong in a way that only shows at high inclination.'),
  ('welldesign', 'intermediate', 'module', 'm02-the-iscwsa-model', 13, 'This implementation matches the published per-source values to what order?', '["To roughly a part in a hundred million million, over a hundred and eight checked rows.", "To about one percent, which is typical.", "To three significant figures, which is all the published workbook itself reports for each of the source entries.", "To within the published tolerance band, which the maintaining group states alongside the expected results."]'::jsonb, 0, 'Agreement at that level is the same calculation performed twice, in different languages, by different people.'),
  ('welldesign', 'intermediate', 'module', 'm02-the-iscwsa-model', 14, 'Why is machine-precision agreement the CORRECT outcome here?', '["Because both used the same code.", "Because the model is deterministic arithmetic with exactly one right answer.", "Because double precision carries about sixteen digits, so any two implementations agree to fifteen by construction.", "Because the validation case was chosen to be numerically benign, avoiding the singular regions of the model."]'::jsonb, 1, 'Two reservoir simulators agreeing to three percent is a triumph. Two implementations of a closed-form model agreeing to three percent would mean one is wrong.'),
  ('welldesign', 'intermediate', 'module', 'm02-the-iscwsa-model', 15, 'What has a machine-precision match against the workbook NOT established?', '["That the code is free of defects.", "That the implementation handles the singular cases, since the validation well passes through the vertical limit.", "That the model describes reality, which is validation rather than verification.", "That the parameter set used is appropriate for the tool that was actually run in the well being surveyed."]'::jsonb, 2, 'Confusing verification with validation is the commonest overstatement in this subject. Whether the well is where the ellipse says is answered by field experience over decades.'),
  ('welldesign', 'intermediate', 'module', 'm03-reading-the-covariance', 1, 'How many independent numbers are in a station''s NEV covariance?', '["Nine, one per matrix entry.", "Six: three variances on the diagonal and three covariances off it.", "Three, because the matrix is diagonal in the map frame and the off-diagonal terms vanish by construction.", "Twelve, because each of the three directions carries both a systematic and a random component separately."]'::jsonb, 1, 'The matrix is symmetric, so the upper and lower triangles repeat. Six numbers describe an ellipsoid in three dimensions.'),
  ('welldesign', 'intermediate', 'module', 'm03-reading-the-covariance', 2, 'What does a large negative north-east covariance mean?', '["The two errors move oppositely, which tilts the ellipse away from the map axes.", "The north uncertainty is negative.", "The north and east errors are independent, since a negative covariance indicates the absence of a shared source.", "The position is biased to the south and east, which is the direction the covariance sign points toward."]'::jsonb, 0, 'Reading only the diagonal misses it entirely, and the diagonal is what most reports quote.'),
  ('welldesign', 'intermediate', 'module', 'm03-reading-the-covariance', 3, 'What are the three borehole-frame directions?', '["North, east, and vertical.", "Build, turn, and advance, corresponding to the three ways the assembly can move the bit from a given attitude.", "Highside, lateral, and along hole.", "Radial, tangential, and axial, measured from the centre of curvature of the arc through the station."]'::jsonb, 2, 'They rotate with the well, which is why they answer questions the map frame cannot.'),
  ('welldesign', 'intermediate', 'module', 'm03-reading-the-covariance', 4, 'Why does lateral uncertainty have no vertical component?', '["Because the model sets it to zero.", "Because lateral error comes only from azimuth, and an azimuth error moves the position horizontally by definition.", "Because the vertical component is carried entirely by the along-hole direction in a horizontal well.", "Because highside is defined in the vertical plane containing the hole, so lateral is horizontal."]'::jsonb, 3, 'That is a consequence of the frame''s definition, and it is why lateral is the direction anti-collision cares about most.'),
  ('welldesign', 'intermediate', 'module', 'm03-reading-the-covariance', 5, 'What does along-hole uncertainty decide?', '["Whether two wells will collide.", "Where a formation top, a casing shoe, or a perforation interval actually is.", "Whether a horizontal well is inside the reservoir window, since the reservoir is described in measured depth.", "How far the ellipse extends across the hole, which is what a traveling cylinder plot displays at each depth."]'::jsonb, 1, 'Ten metres of along-hole uncertainty in a lateral is not a problem. Ten metres at a casing point that has to land in a particular shale is.'),
  ('welldesign', 'intermediate', 'module', 'm03-reading-the-covariance', 6, 'Which sources pay for the uncertainty in position measured along the well?', '["The three depth-only sources: reference, scale factor, and stretch.", "Magnetometer bias on the axial sensor.", "The accumulated inclination error, which converts directly into an error in position measured along the hole.", "The survey interval, since a coarser interval leaves more depth between the stations that are actually measured."]'::jsonb, 0, 'They are systematic, so it grows roughly linearly with depth. About one part in a thousand is representative for a pipe tally.'),
  ('welldesign', 'intermediate', 'module', 'm03-reading-the-covariance', 7, 'What drives highside uncertainty?', '["Depth reference errors.", "Azimuth errors, since highside is perpendicular to the hole and azimuth controls the perpendicular directions.", "Inclination errors, from the accelerometers and from assembly sag.", "The declination, which is a global source and therefore contributes to every direction equally at every station."]'::jsonb, 2, 'Sag is worth naming because it is one of the few sources with a large vertical component: it biases inclination directly.'),
  ('welldesign', 'intermediate', 'module', 'm03-reading-the-covariance', 8, 'Why does highside uncertainty matter to a geosteering job?', '["Because it sets the lateral length.", "Because it determines the measured depth at which the well enters the reservoir, which is what the driller steers to.", "Because it is the only component that a gyro survey can reduce, and geosteering wells are surveyed with gyros.", "Because it says whether the model can tell you if you are in the pay at all."]'::jsonb, 3, 'In a three-metre reservoir window with a highside sigma of tens of metres, the model has nothing useful to say, which is exactly why geosteering exists.'),
  ('welldesign', 'intermediate', 'module', 'm03-reading-the-covariance', 9, 'How is the horizontal ellipse constructed?', '["By taking the north-east block of the covariance and finding its eigenvalues and eigenvectors.", "By projecting the ellipsoid onto the plan.", "By taking the square roots of the north and east variances, which give the semi-major and semi-minor axes directly.", "By rotating the covariance into the borehole frame and dropping the along-hole row and column."]'::jsonb, 0, 'The eigenvectors are the axis directions. The square roots of the eigenvalues, times a confidence factor, are the semi-axis lengths.'),
  ('welldesign', 'intermediate', 'module', 'm03-reading-the-covariance', 10, 'Why is the horizontal projection the one everybody quotes?', '["Because the vertical error is small.", "Because wells, targets, and lease boundaries are all drawn in plan.", "Because the vertical component of the covariance is not returned by the error model, only the horizontal block.", "Because anti-collision is defined in the standard as a horizontal separation between the two well centrelines."]'::jsonb, 1, 'It is also the right projection when two wells are at similar depths, which is the usual case.'),
  ('welldesign', 'intermediate', 'module', 'm03-reading-the-covariance', 11, 'What does the horizontal ellipse leave out?', '["The azimuth of the major axis.", "The correlation between north and east, which is discarded when the block is reduced to two semi-axis lengths.", "The vertical component entirely.", "The along-hole direction, which is dropped because it lies outside the plane the ellipse is drawn in."]'::jsonb, 2, 'That is fine for two objects at the same depth and wrong for a well passing above another one. Clearance uses the full three-dimensional covariance.'),
  ('welldesign', 'intermediate', 'module', 'm03-reading-the-covariance', 12, 'On a horizontal well, why is the semi-minor axis close to the along-hole sigma?', '["It is a numerical coincidence.", "Because the semi-minor axis is by definition the smallest sigma in any direction, and along hole is always the smallest.", "Because the eigenvalue decomposition returns the axes in order, and the along-hole variance is always the second one.", "Because the along-hole direction is itself horizontal, so it appears in the horizontal projection."]'::jsonb, 3, 'The along-hole direction is the well-determined one, so it shows up as the short axis of a dramatically elongated ellipse.'),
  ('welldesign', 'intermediate', 'module', 'm03-reading-the-covariance', 13, 'What is the probability of lying inside a two-sigma ellipse in two dimensions?', '["About 86.5 percent.", "About 95.4 percent, as in one dimension.", "About 99.7 percent, since two dimensions accumulate the probability of both axes being within their own bounds.", "It depends on the shape of the ellipse, since an elongated ellipse covers a different fraction than a circular one."]'::jsonb, 0, 'The two-dimensional rule is P equals one minus the exponential of minus k squared over two. The one-dimensional intuition does not carry.'),
  ('welldesign', 'intermediate', 'module', 'm03-reading-the-covariance', 14, 'What k gives 95 percent coverage in two dimensions?', '["Exactly 1.96, as in one dimension.", "About 2.7955.", "It cannot be stated without knowing the eigenvalues, because coverage depends on the ellipse''s aspect ratio.", "About 2.0, since two dimensions require two sigma to reach the same coverage one sigma gives in one dimension."]'::jsonb, 1, 'Two sigma in two dimensions is only 86.5 percent. Quoting a two-sigma ellipse as ninety-five percent is a common and material error.'),
  ('welldesign', 'intermediate', 'module', 'm03-reading-the-covariance', 15, 'Why does the confidence factor have to be stated with an ellipse?', '["Because the standard requires it.", "Because different confidence factors correspond to different error models, and the model must be identifiable.", "Because the choice of contour scales every number downstream by that factor.", "Because the factor differs between the semi-major and semi-minor axes, so both must be quoted separately."]'::jsonb, 2, 'A covariance describes a distribution. An ellipse is one contour of it, and which contour is a choice rather than a result.'),
  ('welldesign', 'intermediate', 'module', 'm04-the-budget', 1, 'Why rank the error sources at all?', '["Because the standard requires a ranking.", "Because the total covariance cannot be computed until the sources have been ordered by their contribution.", "Because if one source is most of the answer, only that source is worth reducing.", "Because the ranking is fixed for a given tool, so it can be computed once and reused on every well."]'::jsonb, 2, 'Everything spent on the others is effort spent on rounding, and the ranking is not fixed: it changes with attitude.'),
  ('welldesign', 'intermediate', 'module', 'm04-the-budget', 2, 'What scalar summary does the budget panel rank by?', '["The trace, the sum of the three variances, which is frame-independent.", "The semi-major axis of the ellipse.", "The lateral variance alone, which is the component that anti-collision cares about and therefore the operative one.", "The determinant of the three by three covariance, which is proportional to the volume of the error ellipsoid."]'::jsonb, 0, 'Lateral variance alone would be right if anti-collision were the only concern. The trace is the general-purpose choice, and rotating frames does not change it.'),
  ('welldesign', 'intermediate', 'module', 'm04-the-budget', 3, 'What is AMIL?', '["An accelerometer misalignment term.", "Axial magnetic interference, the drill string''s own magnetism reaching the magnetometers.", "The azimuth misalignment of the tool inside the collar, which rotates every reported azimuth by a fixed angle.", "A model-level allowance for interference from adjacent wells, applied wherever two wells run close together."]'::jsonb, 1, 'On the validation well at total depth it pays for well over half the total variance on its own.'),
  ('welldesign', 'intermediate', 'module', 'm04-the-budget', 4, 'Why does AMIL contribute essentially nothing at 1200 m on the validation well?', '["Because the tool is not yet magnetised.", "Because the interference is proportional to measured depth, and 1200 m is too shallow for it to have accumulated.", "Because at vertical the azimuth is undefined, so all azimuth-related sources are excluded from the sum entirely.", "Because the well is still vertical and its weighting has the sine of inclination in it."]'::jsonb, 3, 'At horizontal the sine is one and it is at its maximum, which is why the ranking at the two depths has almost nothing in common.'),
  ('welldesign', 'intermediate', 'module', 'm04-the-budget', 5, 'At 1200 m the well is vertical and the total variance is tiny. Why?', '["The azimuth is barely determined, but the lever arm is zero because there is no horizontal displacement yet.", "Because there are fewer stations above it.", "Because the accelerometers are at their most accurate at vertical, where the axial component of gravity is largest.", "Because the depth sources are the only active ones at vertical, and they are the smallest three in the model."]'::jsonb, 0, 'Large angular uncertainty with no position consequence. The consequence arrives when the well builds angle and gains reach.'),
  ('welldesign', 'intermediate', 'module', 'm04-the-budget', 6, 'Which three sources are depth-only?', '["Bias, scale factor, and misalignment.", "Depth reference, depth scale factor, and the sag term, which biases inclination and therefore the depth integral.", "Depth reference, depth scale factor, and depth stretch.", "The three sources whose propagation mode is global, which by construction affect the depth measurement alone."]'::jsonb, 2, 'The engine identifies them structurally: a source is depth-only if its sensitivity has a depth component everywhere and no attitude component anywhere.'),
  ('welldesign', 'intermediate', 'module', 'm04-the-budget', 7, 'How does a depth error move the position differently from a direction error?', '["It rotates the whole well about the datum.", "It slides the position along the hole rather than swinging it sideways about a point.", "It scales every position by a constant factor, which grows the whole trajectory outward from the surface location.", "It affects only the true vertical depth column, since measured depth does not enter the horizontal accumulation."]'::jsonb, 1, 'A direction error''s displacement grows with the lever arm. A depth error does not grow with anything except depth itself.'),
  ('welldesign', 'intermediate', 'module', 'm04-the-budget', 8, 'Where does depth error land in the borehole frame?', '["Evenly across all three directions.", "In highside, because a depth error changes the true vertical depth and highside is the vertical direction at the hole.", "In lateral, because it displaces the station along a path that is curving and therefore sideways to the current attitude.", "Almost entirely in along hole, and hardly at all in lateral."]'::jsonb, 3, 'That is why depth sources matter for casing points and formation tops, and contribute almost nothing to an anti-collision problem.'),
  ('welldesign', 'intermediate', 'module', 'm04-the-budget', 9, 'Why does a depth error appear in a horizontal well''s plan ellipse but not a vertical well''s?', '["Because along hole is horizontal in one case and vertical in the other.", "Because vertical wells are surveyed less often.", "Because the depth scale factor grows with measured depth, and a horizontal well has far more measured depth than a vertical one.", "Because the plan ellipse is computed from the borehole frame, which is undefined in a vertical well."]'::jsonb, 0, 'Nothing about the depth measurement changed. The same physical error shows up in one report and not the other because of where the hole points.'),
  ('welldesign', 'intermediate', 'module', 'm04-the-budget', 10, 'What is the direct fix for axial magnetic interference?', '["A more accurate magnetometer.", "A shorter survey interval, so that the interference averages out over a larger number of independent readings.", "More non-magnetic collar between the tool and the steel.", "Referencing the azimuths to grid north instead of magnetic north, which removes the magnetic dependence entirely."]'::jsonb, 2, 'The required length is a design calculation per hole section. It costs collars and bottom hole assembly length, and it is a drilling decision rather than a survey one.'),
  ('welldesign', 'intermediate', 'module', 'm04-the-budget', 11, 'What does multi-station analysis do?', '["Averages repeated surveys at one station.", "Solves a whole run of surveys jointly for the interference terms that best explain them.", "Compares the survey against offset wells in the same field, using the shared geology to detect a systematic bias.", "Runs the error model at every station and selects the parameter set that minimises the total covariance."]'::jsonb, 1, 'It works because interference varies with attitude in a known way, so a run covering a range of attitudes can separate it from the true azimuth.'),
  ('welldesign', 'intermediate', 'module', 'm04-the-budget', 12, 'What does in-field referencing remove?', '["The drill string''s own magnetism.", "The dependence on magnetic north entirely, since the surface magnetometer provides an independent true azimuth.", "The accelerometer sag term, by giving an independent measurement of the tool''s attitude at the surface.", "The field model''s error and the daily variation the model cannot capture."]'::jsonb, 3, 'It reduces the declination and field-strength sources, which on this well are the second and third largest. It costs a piece of equipment and a survey to place it.'),
  ('welldesign', 'intermediate', 'module', 'm04-the-budget', 13, 'What does the ranking''s dependence on attitude mean for a budget report?', '["A budget without a station attached describes nothing in particular.", "The report should use the deepest station.", "The ranking should be averaged over all stations, so that the report describes the well rather than one point on it.", "The budget should be quoted per source as a fraction of the total, since fractions are stable even when magnitudes change."]'::jsonb, 0, 'The leading source at total depth does not appear in the top five while the well is vertical. A pie chart without a depth is a pie chart of nothing.'),
  ('welldesign', 'intermediate', 'module', 'm04-the-budget', 14, 'Roughly how many sources account for the great majority of the variance at total depth?', '["All twenty-seven, roughly equally.", "About fifteen, which is why the model carries so many sources rather than collapsing them into a smaller set.", "About five of the twenty-seven.", "Exactly one, since axial magnetic interference accounts for the total to within the precision anyone reports."]'::jsonb, 2, 'The leader is well over half on its own, and the next two together are about a quarter more. The tail is long and small.'),
  ('welldesign', 'intermediate', 'module', 'm04-the-budget', 15, 'Why keep per-source covariances rather than only their sum?', '["Because the sum is numerically unstable.", "Because a model returning only the total could say the answer but not where it came from.", "Because the standard''s validation case publishes per-source values, so they must be retained in order to be checked.", "Because different sources use different propagation modes, which cannot be combined into a single matrix."]'::jsonb, 1, 'The validation check is a real second reason. The first is that a budget is what turns a number into a decision about what to change.'),
  ('welldesign', 'intermediate', 'module', 'm05-using-the-number', 1, 'A well arrives inside the target tolerance radius. Has it hit the target?', '["Yes, by definition of the tolerance.", "Only probably: the true position is somewhere in an ellipse, and the ellipse may be as large as the target.", "No, because a target hit requires the computed position to be within one sigma of the target centre as well.", "Only if the survey was corrected by multi-station analysis, which is what the tolerance is defined against."]'::jsonb, 1, 'Comparing point estimates ignores the uncertainty entirely, and on this well the lateral sigma is comparable to a typical target radius.'),
  ('welldesign', 'intermediate', 'module', 'm05-using-the-number', 2, 'What is the honest form of the target question?', '["The probability that the true position lies inside the target region.", "The distance from the centre.", "Whether the target radius exceeds the semi-major axis of the ellipse at the ninety-five percent confidence factor.", "Whether the computed position and the target centre lie within the sum of their two tolerance radii of each other."]'::jsonb, 0, 'It is an integral of the distribution over the target region, with no closed form for a general shape, so people approximate or Monte Carlo it.'),
  ('welldesign', 'intermediate', 'module', 'm05-using-the-number', 3, 'The expected uncertainty at the target is larger than the target. What does that mean for planning?', '["Nothing: drill and find out.", "The target should be enlarged to match the uncertainty, since a target smaller than the ellipse is not a usable specification.", "The hit cannot be demonstrated whatever happens, so the survey programme has to change.", "The well should be drilled and the position confirmed afterwards with a gyro survey, which has no azimuth uncertainty."]'::jsonb, 2, 'Target size is set by geology rather than preference. The mitigations are planning decisions and they have to be made before the well is drilled.'),
  ('welldesign', 'intermediate', 'module', 'm05-using-the-number', 4, 'Why is vertical position uncertainty usually small?', '["Because depth is counted at surface.", "Because the vertical direction carries no azimuth dependence, and azimuth is the poorest of the three measurements.", "Because the model applies a smaller magnitude to the vertical component of every source''s weighting function.", "Because inclination is measured well and TVD is an integral of its cosine."]'::jsonb, 3, 'Both reasons are real. Almost every other source is azimuth-related and contributes nothing vertically at all.'),
  ('welldesign', 'intermediate', 'module', 'm05-using-the-number', 5, 'At what inclination does an inclination error affect TVD most?', '["Around forty-five degrees.", "At vertical, where TVD equals measured depth.", "At horizontal, where the well gains no vertical depth and any inclination error therefore changes the whole integral.", "It is constant with inclination, because the integral of the cosine is evaluated over the whole well rather than locally."]'::jsonb, 0, 'The derivative of the cosine is the sine, which is zero at vertical. At horizontal the cosine is flat too. TVD error accumulates through the build sections.'),
  ('welldesign', 'intermediate', 'module', 'm05-using-the-number', 6, 'Which two contributors dominate vertical uncertainty?', '["Axial magnetic interference and declination.", "Assembly sag, and depth error resolved vertically.", "The cross-axial accelerometer bias terms, which set the inclination accuracy and therefore the vertical integral.", "The depth reference and the depth scale factor, which are the only two sources with a vertical component at all."]'::jsonb, 1, 'Sag biases inclination directly. Depth resolved vertically is the whole story in a vertical well and nothing in a horizontal one.'),
  ('welldesign', 'intermediate', 'module', 'm05-using-the-number', 7, 'Why does vertical uncertainty matter most in a lateral?', '["Because laterals are surveyed less often.", "Because vertical uncertainty grows fastest at horizontal, where the cosine of the inclination approaches zero.", "Because a thin reservoir gives a window of a few metres of TVD held over a kilometre.", "Because a lateral''s along-hole uncertainty is horizontal, so the vertical component carries the whole ellipse."]'::jsonb, 2, 'A sigma of tens of metres against a window of a few is why geosteering exists rather than trusting the survey.'),
  ('welldesign', 'intermediate', 'module', 'm05-using-the-number', 8, 'How many things must accompany a quoted semi-major axis to make it comparable?', '["One: the confidence factor.", "Two: the confidence factor and the station, since everything else is fixed by the standard the operator uses.", "Three: the confidence factor, the model revision, and the units the axis length is expressed in.", "Five: the confidence factor, the dimension, the model revision, the parameter set, and the station."]'::jsonb, 3, 'Any one of the five missing makes the number incomparable with another number computed the same way.'),
  ('welldesign', 'intermediate', 'module', 'm05-using-the-number', 9, 'Which of the five is most often omitted and moves the number most?', '["The parameter set: a basic set and a corrected set differ substantially on the same well.", "The units the axis is quoted in.", "The station, since a semi-major axis at 1200 m and at 8000 m differ by orders of magnitude on the same well.", "The confidence factor, since a factor of nearly three separates k of one from the ninety-five percent factor."]'::jsonb, 0, 'The confidence factor is a large effect and it is usually stated. The parameter set is a large effect that usually is not.'),
  ('welldesign', 'intermediate', 'module', 'm05-using-the-number', 10, 'Why can a reader not infer the confidence factor from a stated percentage?', '["Because percentages are rounded.", "Because the two-dimensional percentages do not match the one-dimensional ones.", "Because the percentage depends on the aspect ratio of the ellipse, so the same k gives different coverage on different wells.", "Because the model reports coverage at three sigma only, and other percentages are extrapolated by the software."]'::jsonb, 1, 'Ninety-five percent is k of 2.7955 in two dimensions and 1.96 in one. A reader who assumes the wrong dimension is off by nearly half.'),
  ('welldesign', 'intermediate', 'module', 'm05-using-the-number', 11, 'What is a gross error, and does the model cover it?', '["A source whose magnitude exceeds its bound.", "An error larger than three sigma, which the model covers only in the tails of the assumed normal distribution.", "A station at the wrong depth or from the wrong well, and no, the model excludes it.", "A systematic error that was not corrected before the survey was reported, which the covariance absorbs implicitly."]'::jsonb, 2, 'The standard''s own documentation says so: the model describes the spread of CORRECT measurements. The defence is quality control, not a bigger ellipse.'),
  ('welldesign', 'intermediate', 'module', 'm05-using-the-number', 12, 'What does the survey error model say about the surface position?', '["It includes it as a global source.", "It includes it in the depth reference term, which carries the offset between the datum and the wellhead elevation.", "It assumes a default of half a metre, which the standard states and which the user can override in the header.", "Nothing: it starts at the tie-on and accumulates from there."]'::jsonb, 3, 'The clearance calculation adds a surface position term explicitly as a separate parameter, precisely because the survey model does not carry it.'),
  ('welldesign', 'intermediate', 'module', 'm05-using-the-number', 13, 'Why do clearance calculations add a wellbore radius for each well?', '["Because the model gives the uncertainty of the centreline and a hole has a diameter.", "Because the radius is a source of error.", "Because the standard''s separation factor is defined between hole walls rather than between the two centrelines.", "Because a washed-out hole has a larger uncertainty, and the radius is how that increase enters the calculation."]'::jsonb, 0, 'The standard clearance examples use 0.4572 and 0.3048 m, which are eighteen and twelve inch holes.'),
  ('welldesign', 'intermediate', 'module', 'm05-using-the-number', 14, 'In what sense is the ellipse a lower bound rather than a worst case?', '["Because it is quoted at one sigma.", "Because gross errors, surface position, hole radius, and model error all sit outside it.", "Because the model''s parameter magnitudes are chosen conservatively, so the true spread is usually smaller than reported.", "Because the confidence factor is a choice, and any ellipse can be enlarged by choosing a larger one."]'::jsonb, 1, 'Enlarging the confidence factor does not add the missing categories. They are absent from the covariance regardless of k.'),
  ('welldesign', 'intermediate', 'module', 'm05-using-the-number', 15, 'What is model error, in this context?', '["A defect in the implementation code.", "The difference between the model''s answer and the answer a competing model gives on the same well and tool.", "That the magnitudes are consensus estimates and the propagation modes are a simplification.", "The residual after the published validation workbook has been reproduced to machine precision at every station."]'::jsonb, 2, 'The weighting functions are derived under assumptions about sensor behaviour. Reproducing the workbook exactly says nothing about any of that.'),
  ('welldesign', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'Having finished the Professional modules, which skill have you earned?', '["Compile and check a trajectory design.", "Judge whether two wells are far enough apart to drill safely, using a separation factor and its thresholds.", "Quantify how far the reported position could be from the true one, and say what pays for it.", "Correct a magnetic survey for interference, using multi-station analysis over a run of survey stations."]'::jsonb, 2, 'The separation question is the expert tier. Multi-station analysis is named here as a mitigation and not taught as a calculation.'),
  ('welldesign', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'In one sentence, what is the shape of the answer on the validation well?', '["A long thin ellipse pointing across the well, dominated by a few sources that change with depth.", "A circle whose radius grows with depth.", "A sphere of possible positions whose radius is set by the largest single error source at that station.", "A vertical ellipse, since inclination is measured well and azimuth is not, which makes the vertical axis the short one."]'::jsonb, 0, 'It is nine times longer than it is wide, and it points across the well because lateral is more than four times highside.'),
  ('welldesign', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'Which two of the three borehole components govern collision and containment?', '["Along hole governs both of them.", "Lateral governs collision, and highside governs whether the well is in the reservoir.", "Highside governs collision, since two wells at the same depth are separated in the vertical plane between them.", "Lateral governs both, since the ellipse is elongated in the lateral direction and dominates every question asked of it."]'::jsonb, 1, 'Along hole governs depth control: where a formation top, a casing shoe, or a perforation interval actually is.'),
  ('welldesign', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'Why does the factor of ten between random and systematic matter so much?', '["Because it sets the survey interval.", "Because random sources can be reduced by averaging, so the model reports only the systematic part of the total.", "Because the standard requires systematic sources to be quoted separately from random ones in any report.", "Because it means the biggest contributors are the ones that do not improve with more stations."]'::jsonb, 3, 'Over a hundred stations, a systematic source of a given size is ten times a random one of the same size. That is why surveying more often does not help.'),
  ('welldesign', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'What single difference in the arithmetic produces that factor of ten?', '["The order of squaring: random adds in variance, systematic adds in amplitude first.", "The number of sources in the model.", "The weighting functions, which are evaluated per station for random sources and once per run for systematic ones.", "The propagation matrix, which is diagonal for random sources and fully populated for systematic ones."]'::jsonb, 0, 'It is a single choice about where the square goes, and it changes the answer by an order of magnitude on a real well.'),
  ('welldesign', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'Why is the map-frame covariance the wrong six numbers to look at?', '["Because the map frame is not right handed.", "Because the map frame changes with the projection used, so the numbers are not comparable between operators.", "Because the diagonal alone hides a large negative correlation and a strongly tilted ellipse.", "Because the model computes in the borehole frame internally and the map frame is a lossy conversion of it."]'::jsonb, 2, 'On this well the north-east covariance is large and negative, and reading only the variances gives a picture that is true and useless.'),
  ('welldesign', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'What is the two-dimensional confidence at k equal to one?', '["About 68.3 percent, as in one dimension.", "About 39.3 percent.", "It depends on the ellipse aspect ratio, so no single figure applies across different wells and stations.", "About 86.5 percent, which is the figure most anti-collision procedures adopt as their working confidence."]'::jsonb, 1, 'The one-dimensional intuition is worth unlearning here, because a one-sigma ellipse covers well under half the distribution.'),
  ('welldesign', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'What does the capstone ask you to compute?', '["A separation factor between two wells.", "The true vertical depth of a published worked example, and the error a weaker calculation method makes on it.", "The non-magnetic spacing required for a given hole section at a stated inclination and azimuth.", "Six numbers from one station of the validation well, at its deepest station."]'::jsonb, 3, 'Covariance entry, two borehole sigmas, an ellipse semi-axis, an ellipse azimuth, and one source''s share of the total.'),
  ('welldesign', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'Why does field five of the capstone not depend on the confidence factor?', '["Because scaling an ellipse does not rotate it.", "Because the azimuth is measured, not derived.", "Because the factor cancels between the semi-major and semi-minor axes, leaving the orientation unchanged.", "Because the standard fixes the azimuth convention at k equal to one, so no other factor is ever applied to it."]'::jsonb, 0, 'The eigenvectors are unchanged by multiplying the eigenvalues by a common factor. Only the axis lengths move.'),
  ('welldesign', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'What must be true of the header for the capstone answers to reproduce?', '["It must use grid north azimuths.", "It must be recomputed from the well''s surface location using a current world magnetic model evaluation.", "It must be the fixture''s own, including the vertical inclination limit it states.", "It must state a total field and dip that match the model''s default values rather than the fixture''s."]'::jsonb, 2, 'Total field, dip, declination, convergence, azimuth reference, gravity, and the vertical limit. Changing any of them changes the answer.'),
  ('welldesign', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'What is the number of error sources in the standard model used here, and how many are depth-only?', '["Twelve, of which one is depth-only.", "Twenty-seven, of which three are depth-only.", "Twenty-seven, of which five are depth-only, corresponding to the five that dominate the budget at total depth.", "It varies by tool, since the parameter set determines which of the available sources are active on a given run."]'::jsonb, 1, 'The three are identified structurally: a depth component everywhere and no attitude component anywhere.'),
  ('welldesign', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'What habit does this tier ask you to carry forward about budgets?', '["Always rank by the lateral variance.", "Always quote the budget as percentages rather than absolute variances, since percentages are comparable between wells.", "Always compute the budget at the shallowest station, where the sources are most nearly independent of geometry.", "Attach a depth to every one, because the ranking changes completely with attitude."]'::jsonb, 3, 'The leading source at total depth is not in the top five while the well is vertical. That is the whole reason a station has to be named.'),
  ('welldesign', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'Before interpreting six numbers in north, east and vertical, what should you do?', '["Rotate into the borehole frame before interpreting anything.", "Always report at k equal to one.", "Always take the square root of the trace, which is a frame-independent summary of the total uncertainty at a station.", "Always compare the covariance against the offset wells in the field before drawing any conclusion from it."]'::jsonb, 0, 'Along hole, highside, and lateral answer three different questions, and on this well they differ by a factor of four.'),
  ('welldesign', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'What does the expert tier add to what this tier computed?', '["A more accurate error model revision.", "A correction for magnetic interference, which reduces the largest source this tier identified in the budget.", "A second well, and the separation between the two.", "The propagation of uncertainty into true vertical depth, which this tier computed only in the horizontal plane."]'::jsonb, 2, 'The ellipse this tier produced exists to answer a question that involves two wells, and that question is the next tier.'),
  ('welldesign', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'Why does the expert tier need the kickoff depth in a shared-slot case?', '["Because the kickoff sets the survey interval.", "Because two wells from one slot share their uncertainty above the kickoff, and the common part must be removed.", "Because the separation factor is undefined above the kickoff, where the two wells occupy the same hole.", "Because the surface position term applies only below the kickoff, where the two trajectories begin to diverge."]'::jsonb, 1, 'Adding two covariances that share a common cause double counts it, and that overstates the separation the pair actually has.'),
  ('welldesign', 'intermediate', 'final', null, 1, 'A colleague proposes surveying every 10 m instead of every 30 m to halve the uncertainty. What do you tell them?', '["It will work but cost rig time.", "The dominant sources are systematic, and those do not improve with more stations at all.", "It will help, because the minimum curvature assumption has less ground to cover and the position error falls with interval.", "It will help only below the build section, where the attitude changes fastest between consecutive survey stations."]'::jsonb, 1, 'Random sources improve as the square root of the count. They are not what is paying for the ellipse on a horizontal well.'),
  ('welldesign', 'intermediate', 'final', null, 2, 'The error model refuses to run and names two missing header values. What are they and why?', '["Total field and dip, because every magnetometer weighting function contains both.", "Declination and convergence.", "Latitude and longitude, from which the field model would compute everything else the calculation requires.", "The tool type and the survey interval, which together select which of the twenty-seven sources are active."]'::jsonb, 0, 'Without them a sensor error in nanotesla cannot be converted into an azimuth error, so the refusal is protection rather than inconvenience.'),
  ('welldesign', 'intermediate', 'final', null, 3, 'A report quotes an uncertainty of 267 metres at total depth and nothing else. What is your first question?', '["Which service company produced it.", "Whether the figure is in metres or feet, since the two differ by a factor that would change any comparison.", "At what confidence factor, since k of one and the ninety-five percent factor differ by nearly three.", "Whether it was computed at the deepest station or averaged over the whole well below the last casing shoe."]'::jsonb, 2, 'The station is also missing, along with the dimension, the model revision, and the parameter set. Five things, and this is the first.'),
  ('welldesign', 'intermediate', 'final', null, 4, 'Two vendors quote different ellipses for the same well and tool. What is the likeliest cause?', '["One of them has a coding defect.", "Different survey calculation methods, since the position accumulation feeds directly into the covariance at every station.", "Different station intervals, since a finer interval produces more stations and therefore a larger systematic accumulation.", "Different parameter sets, which is the omission that moves the number most."]'::jsonb, 3, 'A basic MWD set and an in-field-referenced, multi-station-corrected set give substantially different answers on the same well.'),
  ('welldesign', 'intermediate', 'final', null, 5, 'A geologist asks whether the lateral is inside a 3 m reservoir window. What does the model tell you?', '["That the well is inside with high confidence.", "That highside uncertainty is far larger than the window, so the model cannot answer it.", "That the answer depends on the lateral component, which is the largest of the three borehole directions on this well.", "That the along-hole uncertainty determines it, since reservoir entry is quoted at a measured depth along the well."]'::jsonb, 1, 'That gap between what is asked and what the model can say is precisely why geosteering exists as a separate discipline.'),
  ('welldesign', 'intermediate', 'final', null, 6, 'Your budget at total depth shows one source at well over half the variance. What is the direct engineering fix?', '["More non-magnetic collar between the tool and the drill string steel.", "A gyro survey instead of a magnetic one.", "A shorter survey interval through the section where that source contributes most to the total variance.", "Referencing the azimuths to grid north, which removes the dependence on the magnetic field model entirely."]'::jsonb, 0, 'A gyro removes the magnetic problem and brings its own error model. The direct fix for axial interference is spacing, and it is a drilling decision.'),
  ('welldesign', 'intermediate', 'final', null, 7, 'The same well''s budget at 1200 m has almost nothing in common with the one at 8000 m. Is something wrong?', '["Yes, the model has been misconfigured.", "No, but only because the depth-only sources dominate at shallow depth and the attitude sources dominate deeper.", "No: the weightings depend on attitude, and the well is vertical at one depth and horizontal at the other.", "Yes, a budget should be stable with depth because the tool and its parameter set do not change during the run."]'::jsonb, 2, 'The leading source at total depth has the sine of inclination in its weighting, which is zero while the well is vertical.'),
  ('welldesign', 'intermediate', 'final', null, 8, 'A survey shows large uncertainty at 1200 m in angle but tiny position variance. Explain.', '["The model suppresses shallow errors.", "The azimuth is poorly determined near vertical, and there is no horizontal lever arm to multiply it by.", "The accelerometers are most accurate at vertical, so the inclination error is negligible and the position follows.", "Only the depth sources are active at vertical, and they are the three smallest sources in the standard model."]'::jsonb, 1, 'Large angular uncertainty with no position consequence. The consequence arrives when the well builds angle and gains reach.'),
  ('welldesign', 'intermediate', 'final', null, 9, 'You are asked to reduce the second and third largest sources on a well. What do you propose?', '["A longer non-magnetic collar.", "Multi-station analysis, which solves a run of surveys jointly for the interference terms that best explain them.", "A shorter survey interval, which reduces the systematic accumulation over the length of the survey run.", "In-field referencing, which removes the field model error and the daily variation."]'::jsonb, 3, 'The second and third on this well are declination and field-strength reference terms, and a surface magnetometer is what addresses both.'),
  ('welldesign', 'intermediate', 'final', null, 10, 'A report quotes a two-sigma ellipse as ninety-five percent. Is that right?', '["Yes, that is the standard convention.", "No, but the difference is negligible for practical purposes since both round to the same confidence band.", "No: two sigma in two dimensions is about 86.5 percent, and ninety-five needs about 2.7955.", "It depends on the aspect ratio of the ellipse, so the statement cannot be judged without the two semi-axes."]'::jsonb, 2, 'The one-dimensional intuition does not carry. This is a common and material error, and it understates the ellipse people are relying on.'),
  ('welldesign', 'intermediate', 'final', null, 11, 'A well''s plan ellipse is nine times longer than it is wide. What does that tell you?', '["Azimuth is far worse determined than depth, and the long axis points across the hole.", "The survey has a gross error in it.", "The well is close to vertical, where the azimuth is undefined and the ellipse degenerates toward a line.", "The station interval is too coarse, so the accumulated position error has grown along one direction only."]'::jsonb, 0, 'The short axis is close to the along-hole sigma because in a horizontal well the along-hole direction lies in the horizontal plane.'),
  ('welldesign', 'intermediate', 'final', null, 12, 'You need to place a casing shoe in a specific 5 m shale. Which uncertainty component governs?', '["Lateral, driven by azimuth error.", "Along hole, driven by the three depth-only sources.", "Highside, since the shale is defined in true vertical depth and highside is the vertical direction at the hole.", "The semi-major axis of the plan ellipse, since that is the largest of the reported uncertainties at the station."]'::jsonb, 1, 'Highside matters for whether the hole is above or below the shale. Along hole is where the shoe is along the well, which is what the driller sets.'),
  ('welldesign', 'intermediate', 'final', null, 13, 'A survey listing was recorded with azimuths referenced to grid north but the header says true. What happens?', '["The model refuses to run.", "Only the magnetometer sources are affected, since the accelerometers have no azimuth dependence in their weightings.", "The totals stay correct and the per-source breakdown is scrambled, because the sum is invariant under the rotation.", "The whole covariance is rotated, and nothing in the output reveals it."]'::jsonb, 3, 'A rotated answer looks entirely plausible. That is why the header has to be read rather than assumed to match the file.'),
  ('welldesign', 'intermediate', 'final', null, 14, 'Your team wants to add gross error risk into the covariance by inflating it. What is the objection?', '["Inflating a covariance is not defined.", "The standard prohibits any modification of the published parameter magnitudes for any reason whatsoever.", "The model describes the spread of correct measurements; a bigger ellipse does not detect a wrong one.", "Gross errors are already included in the model, through the tails of the assumed normal distributions."]'::jsonb, 2, 'The defence against a station from the wrong well is quality control on the survey. An inflated ellipse just makes every good survey look worse.'),
  ('welldesign', 'intermediate', 'final', null, 15, 'A shallow anti-collision problem is dominated by a half metre term. Where does it come from?', '["The surface position, which the survey error model does not carry at all.", "The depth reference source.", "The wellbore radius, which the standard clearance examples set at 0.4572 and 0.3048 metres for the two wells.", "The declination, which is global and therefore applies from the surface downward with its full magnitude."]'::jsonb, 0, 'The survey model starts at the tie-on and accumulates. The clearance calculation adds the surface term separately for exactly that reason.'),
  ('welldesign', 'intermediate', 'final', null, 16, 'Why does the covariance say nothing about hole diameter?', '["Because diameter is not an error.", "Because it describes the uncertainty of the centreline, not the extent of the hole.", "Because hole diameter varies along the well and the model returns one covariance per station rather than a range.", "Because a reamed or washed-out hole changes the survey tool''s position within it, which is a separate correction."]'::jsonb, 1, 'Clearance calculations add a radius for each well as a separate input, and the standard examples use eighteen and twelve inch values.'),
  ('welldesign', 'intermediate', 'final', null, 17, 'A colleague says the ellipse is the worst case. Correct them.', '["It is the worst case at three sigma.", "It is the average case, since the parameter magnitudes are consensus estimates rather than conservative bounds.", "It is the worst case only in the lateral direction, which is the one anti-collision is concerned with.", "It is a lower bound: gross errors, surface position, hole radius, and model error all sit outside it."]'::jsonb, 3, 'Choosing a larger confidence factor scales what is inside the model. It does not add any of the four missing categories.'),
  ('welldesign', 'intermediate', 'final', null, 18, 'Your code agrees with the workbook to fourteen digits. What may you claim?', '["That the ellipse describes the real well.", "That the parameter set is appropriate for the tool that was actually run in the hole being surveyed.", "That the code computes the model correctly, which is verification.", "That the model''s assumptions about sensor behaviour hold at the inclinations the validation well covers."]'::jsonb, 2, 'Whether the model describes reality is validation, answered by field experience over decades. Confusing the two is the commonest overstatement here.'),
  ('welldesign', 'intermediate', 'final', null, 19, 'Two implementations of the model agree to three percent. What do you conclude?', '["One of them is wrong, because the model is deterministic arithmetic with one right answer.", "That agreement is excellent.", "That the two used different parameter sets, which is the only difference that can produce a disagreement of that size.", "That the difference is within the model''s own uncertainty, so neither can be preferred over the other."]'::jsonb, 0, 'Two reservoir simulators at three percent is a triumph. Two implementations of a closed-form model at three percent is a defect in one of them.'),
  ('welldesign', 'intermediate', 'final', null, 20, 'Your survey run covers a wide range of attitudes. What does that make possible?', '["A shorter non-magnetic collar.", "Multi-station analysis, because interference varies with attitude in a known way.", "A better estimate of the depth scale factor, since the range of attitudes exercises the stretch term over its full span.", "A direct measurement of the declination, since the field direction is sampled from several hole orientations."]'::jsonb, 1, 'A run over one attitude carries too little information to separate the interference from the true azimuth. A varied run carries enough.'),
  ('welldesign', 'intermediate', 'final', null, 21, 'A north-south hole at high dip has a poor azimuth. Which part of the model captures that?', '["The propagation mode assignment.", "The vertical inclination limit, which switches formulation where the horizontal field projection becomes small.", "The depth-only flag, which excludes the depth sources from any azimuth-dependent part of the calculation.", "The magnetometer weighting functions, which contain the field strength and the dip."]'::jsonb, 3, 'The dip sets how much of the field is horizontal, and the azimuth is essentially the direction of that horizontal component.'),
  ('welldesign', 'intermediate', 'final', null, 22, 'Why does a bias on the axial magnetometer behave systematically?', '["Because it is corrected at surface.", "Because it depends on the attitude, and the attitude varies smoothly so its effect is correlated between stations.", "Because it is a property of the tool that is fixed for the duration of the run.", "Because it is global, applying identically to every well surveyed with the same tool in the same field."]'::jsonb, 2, 'Sensor noise is different at each reading and is random. Declination is fixed for the location and is global.'),
  ('welldesign', 'intermediate', 'final', null, 23, 'A target''s own position has an uncertainty larger than the well''s. What follows?', '["The hit probability is dominated by the target, not by the survey.", "The well''s ellipse can be ignored.", "The two uncertainties should be subtracted, since the shared geological reference is common to both of them.", "The target should be redefined at the well''s computed position, which is the best available estimate of it."]'::jsonb, 0, 'Reducing the survey uncertainty to zero would not make the hit demonstrable. That is worth knowing before spending money on the survey programme.'),
  ('welldesign', 'intermediate', 'final', null, 24, 'In which section of a well does TVD uncertainty mostly accumulate?', '["In the vertical section above kickoff.", "Through the build sections, where the derivative of the cosine is largest.", "In the horizontal lateral, where the well gains no vertical depth and any inclination error is fully expressed.", "Evenly along the well, since the depth scale factor grows linearly and dominates the vertical component."]'::jsonb, 1, 'At vertical and at horizontal the cosine is flat, so an inclination error changes TVD very little. Around forty-five degrees it matters most.'),
  ('welldesign', 'intermediate', 'final', null, 25, 'Sag is named separately among the sources. Why?', '["Because it is the largest single source.", "Because it depends on the bottom hole assembly rather than on the survey tool, so it is set per section rather than per run.", "Because it is a random source, unlike the other inclination terms, which are systematic over the run.", "Because it biases inclination directly, so it is one of the few with a large vertical component."]'::jsonb, 3, 'The vertical column of a source table is mostly zeros, because nearly everything else is azimuth-related and contributes nothing vertically.'),
  ('welldesign', 'intermediate', 'final', null, 26, 'Your budget ranks by the trace. A colleague wants to rank by lateral variance. Is that wrong?', '["Yes, the trace is the only valid measure.", "Yes, because lateral variance is frame-dependent and would change if the covariance were expressed in the map frame.", "No, it is the right measure if anti-collision is the only concern; the trace is general-purpose.", "No, and the two give the same ranking, since the lateral component dominates the trace on a horizontal well."]'::jsonb, 2, 'The trace is frame-independent, which is a real advantage. It is a choice, and stating which summary was used is part of quoting a budget.'),
  ('welldesign', 'intermediate', 'final', null, 27, 'A well is surveyed with a hundred stations and its neighbour with ten. Which has the better position?', '["Not necessarily the first, because the largest sources do not improve with station count.", "The first, by a factor of about three.", "The first, by a factor of ten, since systematic contributions add in amplitude before being squared.", "The second, because fewer stations means fewer opportunities for a gross error to enter the survey."]'::jsonb, 0, 'The gross error point is a real practical consideration and it is not what the model says. Systematic and global sources are indifferent to how often you survey.'),
  ('welldesign', 'intermediate', 'final', null, 28, 'What is the physical meaning of a negative north-east covariance?', '["That the north variance is smaller.", "That an error making the position more northerly tends to make it less easterly.", "That the north and east errors come from different sources, which is why they have opposite signs in the matrix.", "That the position is systematically biased toward the north-west quadrant relative to the computed one."]'::jsonb, 1, 'It tilts the ellipse away from the map axes, and reading only the diagonal variances misses it completely.'),
  ('welldesign', 'intermediate', 'final', null, 29, 'An ellipse component that is always horizontal. What makes it so?', '["Because azimuth errors are horizontal.", "Because the model projects the lateral direction onto the horizontal plane before reporting it in the borehole frame.", "Because the vertical component of every source is assigned to highside by convention in the standard''s frame definition.", "Because highside is defined in the vertical plane containing the hole."]'::jsonb, 3, 'It falls out of the frame''s definition, and it is why lateral is the direction anti-collision cares about most.'),
  ('welldesign', 'intermediate', 'final', null, 30, 'A plan-view ellipse is used to judge whether a well passes safely above another. What is wrong?', '["Nothing, the plan view is standard.", "The plan view uses a two-dimensional confidence factor, which is not comparable with the three-dimensional one.", "The plan view discards the vertical component, which is exactly what separates them.", "The plan view is computed at one station, and a passing geometry requires the closest approach to be found first."]'::jsonb, 2, 'Two objects at the same depth are the case the plan view handles. A well passing above another is separated vertically, and the ellipse says nothing about it.'),
  ('welldesign', 'intermediate', 'final', null, 31, 'The engine identifies depth-only sources structurally rather than by name. What is the test?', '["A depth sensitivity everywhere and no inclination or azimuth sensitivity anywhere.", "A propagation mode of global.", "A name beginning with the letter D, which the standard''s coding scheme reserves for the depth sources.", "A weighting function whose value does not change with inclination or azimuth at any station in the survey."]'::jsonb, 0, 'Naming them would work on the standard model and break on any other. The structural test survives a change of parameter set.'),
  ('welldesign', 'intermediate', 'final', null, 32, 'A vertical well''s plan ellipse shows no contribution from depth error. Why?', '["Because depth error is not modelled.", "Because along hole is vertical there, so depth error is a vertical error.", "Because a vertical well has no horizontal displacement, so no source contributes to the plan ellipse at all.", "Because the depth sources are systematic and the plan ellipse is built from the random contributions only."]'::jsonb, 1, 'The same physical error appears in a horizontal well''s plan ellipse and not in a vertical well''s. Nothing about the depth measurement changed.'),
  ('welldesign', 'intermediate', 'final', null, 33, 'The dr/dp matrix has entries below the diagonal. What do they represent?', '["Rounding in the accumulation.", "The correlation between inclination and azimuth errors at the same station, which arises from the shared accelerometers.", "The contribution of the ratio factor, which couples each interval to the dogleg it shares with its neighbour.", "The effect of an attitude error at one station on the position at every deeper one."]'::jsonb, 3, 'That structure is the whole reason survey errors accumulate rather than staying local to the station where they entered.'),
  ('welldesign', 'intermediate', 'final', null, 34, 'You are handed a per-source table with only the total covariance. What can you not do?', '["Compute the horizontal ellipse.", "Rotate into the borehole frame, since the rotation must be applied to each source separately before summing.", "Say which source is worth reducing.", "Compare the well against the published validation case, which reports totals only at the four checked depths."]'::jsonb, 2, 'The rotation applies to the sum just as well as to the parts. What is lost is the budget, which is what turns a number into a decision.'),
  ('welldesign', 'intermediate', 'final', null, 35, 'Why does the model convert azimuths to true north before doing anything?', '["Because the position accumulation needs angles in the frame the positions live in.", "Because true north never changes.", "Because the magnetic weighting functions are defined against true north, so the conversion must precede them.", "Because the declination is a global source and is therefore applied once at the start rather than per station."]'::jsonb, 0, 'The magnetic weighting functions need the angle relative to magnetic north, so the model carries both and uses each where it belongs.'),
  ('welldesign', 'intermediate', 'final', null, 36, 'Which mitigation costs nothing but analysis?', '["Additional non-magnetic collars.", "Multi-station analysis, applied to a survey run that already exists.", "In-field referencing, since the surface magnetometer is a one-off purchase amortised over many wells at the location.", "A shorter survey interval, since surveys are taken at connections which happen regardless of the survey programme."]'::jsonb, 1, 'Collars cost money and bottom hole assembly length. A surface magnetometer costs equipment and a survey to place it.'),
  ('welldesign', 'intermediate', 'final', null, 37, 'A single number is quoted for a well''s uncertainty with no station. What is your objection?', '["Uncertainty is not a single number.", "The number must be quoted per source, since the total conceals which contributor is actually paying for it.", "The number is meaningless without a direction, since the ellipse is nine times longer than it is wide.", "The uncertainty at 1200 m and at 8000 m differ by orders of magnitude on the same well."]'::jsonb, 3, 'The direction point is also real. The station is the one that makes the number differ by a factor of thousands rather than nine.'),
  ('welldesign', 'intermediate', 'final', null, 38, 'The validation well ends horizontal at 90 degrees on a 75 degree azimuth. Why does that matter?', '["Because it makes the arithmetic simpler.", "Because a horizontal well is the only geometry in which the borehole frame is fully defined and unambiguous.", "Because it puts the well in the geometry where the axial magnetic terms are at their maximum.", "Because the published workbook only reports values for wells that reach horizontal, so no other geometry can be checked."]'::jsonb, 2, 'Starting vertical and ending horizontal exercises the whole range, including the vertical limit where the formulation switches.'),
  ('welldesign', 'intermediate', 'final', null, 39, 'A plausible implementation passes at low inclination and fails at high. What is the likely cause?', '["A sign convention, a frame choice, or a singular-case override in one of the weighting functions.", "A defect in the depth accumulation.", "An error in the propagation mode assignment, which affects systematic sources more strongly at greater depth.", "A rounding difference that accumulates over stations and only becomes visible once the well has many of them."]'::jsonb, 0, 'That is exactly why a validation case has to exercise the whole range rather than one convenient geometry.'),
  ('welldesign', 'intermediate', 'final', null, 40, 'How would you check that your covariance rotation into the borehole frame is right?', '["Compare against the map-frame diagonal.", "Confirm the trace is unchanged, since a rotation preserves it.", "Confirm the lateral component is the largest, which it must be for any well that has built significant angle.", "Confirm the along-hole component equals the depth-only sources'' total, which is what drives it on any well."]'::jsonb, 1, 'The lateral and along-hole statements are true on this well and are not general. The trace is invariant by construction.'),
  ('welldesign', 'intermediate', 'final', null, 41, 'What is the one-sentence summary you would give a drilling engineer about this tier?', '["Survey more often and the ellipse shrinks.", "The uncertainty is dominated by the depth measurement, which is the only one of the three that is counted rather than sensed.", "The covariance is a worst case, so a well inside its ellipse can be treated as safe without further analysis.", "The position is a measurement with a long thin uncertainty across the hole, paid for by a few sources."]'::jsonb, 3, 'Each of the three wrong answers is a belief people actually hold, and each of them leads to a different bad decision.'),
  ('welldesign', 'intermediate', 'final', null, 42, 'You are asked to reproduce a capstone field and get a different answer. What do you check first?', '["The floating point precision used.", "The confidence factor, since every field in the capstone scales with it and a wrong factor moves them all together.", "The header and the station index, before anything about the calculation.", "The survey calculation method, since the covariance is built on the positions the method produces."]'::jsonb, 2, 'Field five is an azimuth and does not scale with the factor at all, which is a useful discriminator when the numbers disagree.');
